type ZoneScopedTagging = Extract<
  resourceTagging.ListResourceTaggingsResponse["result"][number],
  { zoneId: string }
>;


const narrowTags = (tags: Record<string, unknown>): Record<string, string> =>
  Object.fromEntries(
    Object.entries(tags).map(([k, v]) => [k, String(v)] as const),
  );

